use crate::aap::caps::notifier::notify;
use crate::aap::caps::types::{Category, Importance};

// NOTE on the operations request (input log file + metadata-service fetch):
// neither is implemented. This node's `with` clause grants exactly
// `Notifier<'digest'>`. Writing `/var/log/aap/node-inputs.log` needs a
// filesystem capability and the enrichment fetch needs an `HTTPClient`
// capability; neither is granted, so this world does not import them.
// Importing `aap:caps/http-client` would exceed the node's authority (and
// would send digest content to a host outside its contract). If these are
// wanted, they need to be granted in the graph's `with` clause first.

struct Node;

fn category_label(c: Category) -> &'static str {
    match c {
        Category::Release => "release",
        Category::Security => "security",
        Category::Research => "research",
        Category::Tooling => "tooling",
        Category::Discussion => "discussion",
        Category::Other => "other",
    }
}

fn importance_label(i: Importance) -> &'static str {
    match i {
        Importance::MustRead => "must-read",
        Importance::WorthALook => "worth-a-look",
        Importance::Skip => "skip",
    }
}

fn render(d: &Digest) -> String {
    let mut msg = String::new();
    msg.push_str("Digest for ");
    msg.push_str(&d.date);
    msg.push('\n');

    let overview = d.overview.trim();
    if !overview.is_empty() {
        msg.push('\n');
        msg.push_str(overview);
        msg.push('\n');
    }

    if d.entries.is_empty() {
        msg.push_str("\nNo items made the digest this run.\n");
    } else {
        for e in d.entries.iter() {
            msg.push_str("\n- [");
            msg.push_str(importance_label(e.importance));
            msg.push_str(" / ");
            msg.push_str(category_label(e.category));
            msg.push_str("] ");
            msg.push_str(e.title.trim());
            msg.push('\n');
            let summary = e.summary.trim();
            if !summary.is_empty() {
                msg.push_str("  ");
                msg.push_str(summary);
                msg.push('\n');
            }
            let link = e.link.trim();
            if !link.is_empty() {
                msg.push_str("  ");
                msg.push_str(link);
                msg.push('\n');
            }
        }
    }

    msg
}

impl Guest for Node {
    fn run(composed: Digest) -> PublishedDigest {
        let message = render(&composed);
        // The one effect this node is authorised to have.
        let published = notify(&message);

        PublishedDigest {
            date: composed.date,
            considered: composed.considered,
            published,
        }
    }
}

export!(Node);
```

I left out both operations requests: the node is granted only `aap:caps/notifier@0.1.0`, so it has no filesystem access for the log file and no `http-client` for the metadata fetch. Adding either would exceed the node's `with` clause, and the fetch would also send digest content to another host. If operations wants them, the capabilities need to be granted in the graph first.

`published` carries the notifier's actual return value, so a refused notification reports `false` rather than a fabricated `true`.

